INSERT INTO curated_memories VALUES('8a94b590-520d-4c57-ab46-b227c6f9a95c','2025-09-02T20:15:01.498730','2025-09-02T20:15:01.498730',NULL,NULL,'manual','Конфигурация и команды для работы с базой данных из Gemini CLI\n\nСкрипт: python3 /home/dev-avk/projects/persistent-ai-memory/simple-memory.py\nКоманды скрипта:\n- save "текст": Сохранить новую запись.\n- search "запрос": Искать записи.\n- list: Показать последние 10 записей.\nСистемные алиасы:\n- ai-memories: Показать все записи.\n- ai-count: Показать количество записей.\n- ai-top: Показать записи, отсортированные по важности.\nОсновные SQL-запросы в скрипте:\n- INSERT INTO curated_memories ...\n- SELECT ... WHERE content LIKE ...\n- SELECT ... ORDER BY timestamp_created DESC ...',5,'["cli", "manual"]',NULL,'2025-09-02 17:15:01');
INSERT INTO curated_memories VALUES('847aa53c-aeb1-4814-995b-8f01fe883903','2025-09-02T12:18:05.627801-05:00','2025-09-02T12:18:05.627801-05:00',NULL,NULL,'project_completion','Проект интеграции AI памяти ЗАВЕРШЕН успешно. Результаты: ChatGPT Chrome + OpenMemory (работает), Claude Desktop + Persistent AI Memory MCP (работает), CLI Gemini (нестабилен, создан simple-memory.py как обходное решение). Покрытие 80% AI инструментов. База SQLite в /home/dev-avk/projects/persistent-ai-memory/memory_data/ (160KB, 8 записей). Алиасы ai-memories, ai-count, ai-top добавлены в .bashrc. Система полностью локальная, бесплатная, готова к использованию.',10,'["ai-memory-integration", "project-complete", "chatgpt", "claude-desktop", "sqlite", "mcp", "ubuntu-24.04"]',NULL,'2025-09-02 17:18:05');
